Kctx.reopenDesign_preserves_material_history {current next : Kctx.DesignProposal} {command : Kctx.DesignReopenCommand}
  (h : Kctx.reopenDesign current command = some next) :
  Kctx.sameDesignMaterial current next ∧ next.authored.gateResults = current.authored.gateResults

Kctx.selection_applied_details {s : Kctx.SelectionState} {e : Kctx.Context} {js : List Kctx.SelectionJournalEntry}
  {p : Kctx.SelectionPlan} {trusted : List Kctx.VerifiedSelectionApproval} {retained : List Kctx.KB}
  (h : (Kctx.applySelection s e js p trusted retained).outcome = Kctx.ApplyOutcome.applied) :
  p.expectedSnapshot = s.kb.snapshot ∧
    Kctx.selectionValid s e p trusted retained = true ∧
      Kctx.applySelection s e js p trusted retained =
        { state := Kctx.selectedState s p, journal := { plan := p } :: js, outcome := Kctx.ApplyOutcome.applied }

