  {js : List Kctx.SelectionJournalEntry} {p q : Kctx.SelectionPlan} {trusted : List Kctx.VerifiedSelectionApproval}
  {retained : List Kctx.KB} (h : (Kctx.applySelection s e js p trusted retained).outcome = Kctx.ApplyOutcome.applied)
  (hid : q.id = p.id) (changed : p ≠ q) :
  let result := Kctx.applySelection s e js p trusted retained;
  Kctx.applySelection result.state e result.journal q [] retained =
    { state := result.state, journal := result.journal, outcome := Kctx.ApplyOutcome.inputConflict }

Kctx.selection_exact_retained_refs {s : Kctx.SelectionState} {e : Kctx.Context} {p : Kctx.SelectionPlan}
  {trusted : List Kctx.VerifiedSelectionApproval} {retained : List Kctx.KB}
  (h : Kctx.selectionValid s e p trusted retained = true) :
  ∃ target,
    List.find? (fun k => k.snapshot == p.targetSnapshot) retained = some target ∧
      p.selected = List.map Kctx.Claim.ref target.claims ∧ Kctx.extendsKB target s.kb = true

